    document.getElementById('add').addEventListener('submit', function (e) {
      e.preventDefault();
      var input = document.getElementById('name');
      var name = input.value.trim();
      if (!name) return;
      var all = load();
      all.push({ name: name, days: [] });
      save(all);
      input.value = '';
      render();
    });
    render();
  });
})();
